package org.apache.commons.math.optimization.fitting;

import org.apache.commons.lang3.builder.EqualsBuilder;
import org.junit.*;
import static org.junit.Assert.*;

public class WeightedObservedPointSymflowerTest {
	@Test
	public void WeightedObservedPoint2() {
		double weight = 0.0D;
		double x = 0.0D;
		double y = 0.0D;
		WeightedObservedPoint expected = new WeightedObservedPoint(0.0D, 0.0D, 0.0D);
		WeightedObservedPoint actual = new WeightedObservedPoint(weight, x, y);

		assertTrue(EqualsBuilder.reflectionEquals(expected, actual, false, null, true));
	}

	@Test
	public void getWeight3() {
		WeightedObservedPoint w = new WeightedObservedPoint(0., 0., 0.);
		double expected = 0.;
		double actual = w.getWeight();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void getX4() {
		WeightedObservedPoint w = new WeightedObservedPoint(0., 0., 0.);
		double expected = 0.;
		double actual = w.getX();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void getY5() {
		WeightedObservedPoint w = new WeightedObservedPoint(0., 0., 0.);
		double expected = 0.;
		double actual = w.getY();

		assertEquals(expected, actual, 0.0000001D);
	}
}
